-- 010_replace_questions.sql
-- Replace all existing questions with 500 new curated questions across 6 categories.

-- Clear adaptive history (old question IDs are gone)
delete from public.question_history;

-- Drop FK from answers so we can replace questions without cascading answer history
alter table public.answers drop constraint if exists answers_question_id_fkey;

-- Replace all questions
delete from public.questions;

insert into public.questions (id, rank, category_id, category_name, question_text, frequency, difficulty, answer_format, time_limit_seconds, notes)
values
